    @BeforeEach void refresh()throws Exception{new Stage1PersistenceTest().freshManagerSessions();category=Stage1BusinessBoundaryTest.category("0","S1_TEST"+db.id(),0,200).get("id").getAsString();call(post(Stage1Routes.MANAGER+"/categories/"+category+"/enable"),operator,map("requestId",req(),"expectedVersion",0,"reason","S1_TEST独立用例类目"),200);}
    static OwnerFixture ready()throws Exception{var owner=ownerFixture();String agreement=agreementFixture(owner,0,LocalDate.now(Stage1Rules.ZONE),null);ruleFixture(owner,agreement,0);deliveryFixture(owner);String config=channelConfigFixture(0),relation=channelRelationFixture(owner,config);var row=relationCommand(relation,1,"submit");for(int i=0;i<3;i++)row=relationCommand(relation,row.get("version").getAsLong(),"query");relationCommand(relation,row.get("version").getAsLong(),"enable");return owner;}
    static JsonObject createGoods(OwnerFixture owner,int quantity,List<String> methods,boolean listed)throws Exception{var payload=object(goodsPayload(unitFixture(),upload(owner.login().session(),Stage1Routes.STORE,"GOODS"),quantity));payload.add("methods",GSON.toJsonTree(methods));if(methods.contains("EXPRESS"))payload.getAsJsonArray("skus").get(0).getAsJsonObject().addProperty("weightGram",1);var row=call(post(Stage1Routes.STORE+"/goods"),owner.login().session(),map("requestId",req(),"payload",payload),200);String id=row.getAsJsonObject("goods").get("id").getAsString();if(listed){call(post(Stage1Routes.STORE+"/goods/"+id+"/submit"),owner.login().session(),map("requestId",req(),"expectedVersion",0),200);call(post(Stage1Routes.MANAGER+"/goods/"+id+"/approve"),reviewer,map("requestId",req(),"expectedVersion",1,"contentVersion",0),200);row=call(post(Stage1Routes.STORE+"/goods/"+id+"/list"),owner.login().session(),map("requestId",req(),"expectedVersion",2),200);}return row;}
    @Test void workbenchCountsNativeSpusAndEveryCardMatchesItsFilteredList()throws Exception{
        var owner=ready();call(post(Stage1Routes.STORE+"/goods"),owner.login().session(),map("requestId",req(),"payload",map("name","S1_TEST未完整草稿")),200);
        createGoods(owner,0,List.of("MERCHANT_DELIVERY"),false);createGoods(owner,2,List.of("MERCHANT_DELIVERY"),false);createGoods(owner,0,List.of("MERCHANT_DELIVERY"),true);var last=createGoods(owner,3,List.of("MERCHANT_DELIVERY"),true);
        var summary=call(get(Stage1Routes.STORE+"/workbench"),owner.login().session(),null,200);var counts=summary.getAsJsonObject("goods");assertEquals(5,counts.get("total").getAsLong());assertEquals(3,counts.get("draft").getAsLong());assertEquals(2,counts.get("logicallyListed").getAsLong());assertEquals(1,counts.get("saleable").getAsLong());assertEquals(4,counts.get("unavailable").getAsLong());assertEquals(2,counts.get("outOfStock").getAsLong());assertEquals(1,counts.get("incomplete").getAsLong());assertTrue(summary.has("evaluatedAt"));assertFalse(summary.toString().matches(".*(?:orderCount|revenue|salesAmount).*"));
        var filters=Map.of("draft",new String[]{"status","DRAFT"},"pending",new String[]{"status","SUBMITTED"},"rejected",new String[]{"status","REJECTED"},"logicallyListed",new String[]{"marketStatus","UPPER"},"unlisted",new String[]{"marketStatus","DOWN"},"saleable",new String[]{"saleability","SALEABLE"},"unavailable",new String[]{"saleability","UNSALEABLE"},"outOfStock",new String[]{"stockState","OUT_OF_STOCK"},"incomplete",new String[]{"stockState","INCOMPLETE"},"restricted",new String[]{"forced","true"});
        for(var entry:filters.entrySet()){var result=call(get(Stage1Routes.STORE+"/goods").param(entry.getValue()[0],entry.getValue()[1]),owner.login().session(),null,200);assertEquals(counts.get(entry.getKey()).getAsLong(),result.get("total").getAsLong(),entry.getKey());}
        String sku=last.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString();call(put(Stage1Routes.STORE+"/skus/"+sku+"/stock"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"targetQuantity",0,"reason","S1_TEST统计即时更新"),200);var updated=call(get(Stage1Routes.STORE+"/workbench"),owner.login().session(),null,200).getAsJsonObject("goods");assertEquals(0,updated.get("saleable").getAsLong());assertEquals(3,updated.get("outOfStock").getAsLong());assertEquals(1,updated.get("incomplete").getAsLong());assertEquals(5,updated.get("total").getAsLong());
        var other=ownerFixture();call(get(Stage1Routes.STORE+"/workbench").param("storeId",owner.store()),other.login().session(),null,403);assertEquals(0,call(get(Stage1Routes.STORE+"/workbench"),other.login().session(),null,200).getAsJsonObject("goods").get("total").getAsLong());
        observations.add(map("case","M10-statistics","spus",5,"matchedCardFilters",10,"incompleteIsNotOutOfStock",true,"noMoneyMetrics",true));
    }
    @Test void bnd013ReadOnlyPrecheckIntersectsMethodsAggregatesQuantitiesAndRejectsAllInjectionVariants()throws Exception{
        assertEquals("STOPPED",object(java.nio.file.Files.readString(run.resolve("runtime/apis.json"))).getAsJsonObject("manager").get("state").getAsString(),"Pause the owned worker before global Redis evidence");
        var owner=ready();String pickup=createPointFixture(owner,"COMMUNITY_PICKUP"),redemption=createPointFixture(owner,"STORE_REDEMPTION");for(String point:List.of(pickup,redemption))call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST同店点位"),200);
        var methods=object(deliveryMethods());methods.add("EXPRESS",GSON.toJsonTree(map("enabled",true,"feeCent",100,"nationwide",true)));methods.getAsJsonObject("COMMUNITY_PICKUP").addProperty("enabled",true);methods.getAsJsonObject("STORE_REDEMPTION").addProperty("enabled",true);call(put(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"methods",methods,"reason","S1_TEST方式求交"),200);
        var a=createGoods(owner,10,List.of("MERCHANT_DELIVERY","COMMUNITY_PICKUP"),true);var b=createGoods(owner,10,List.of("EXPRESS","COMMUNITY_PICKUP"),true);String aSku=a.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString(),bSku=b.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString();String code=req();codes.put(code,"S1_TEST_consumer_"+req());var resident=residentLogin.login(code).session();
        var items=List.of(map("skuId",aSku,"quantity",1),map("skuId",bSku,"quantity",1));var command=map("storeId",owner.store(),"items",items);var result=call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200);assertEquals("INPUT_REQUIRED",result.get("status").getAsString());assertEquals("[\"COMMUNITY_PICKUP\"]",result.getAsJsonArray("commonMethods").toString());
        command.put("method","MERCHANT_DELIVERY");assertEquals("BLOCKED",call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200).get("status").getAsString());command.put("method","COMMUNITY_PICKUP");assertEquals("INPUT_REQUIRED",call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200).get("status").getAsString());command.put("pointId",pickup);assertEquals("PASS",call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200).get("status").getAsString());
        command.put("items",List.of(map("skuId",aSku,"quantity",6),map("skuId",aSku,"quantity",4)));var merged=call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200);assertEquals("PASS",merged.get("status").getAsString());assertEquals(1,merged.getAsJsonArray("items").size());assertEquals(10,merged.getAsJsonArray("items").get(0).getAsJsonObject().get("quantity").getAsInt());
        command.put("items",List.of(map("skuId",aSku,"quantity",6),map("skuId",aSku,"quantity",5)));assertTrue(call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200).getAsJsonArray("reasonCodes").toString().contains("OUT_OF_STOCK"));
        for(Object quantity:List.of(0,-1,1.5,10000000,"1")){command.put("items",List.of(map("skuId",aSku,"quantity",quantity)));call(post(Stage1Routes.BUYER+"/precheck"),resident,command,422);}command.put("items",List.of(map("skuId",aSku)));call(post(Stage1Routes.BUYER+"/precheck"),resident,command,422);command.put("items",List.of(map("skuId",aSku,"quantity",9999999),map("skuId",aSku,"quantity",1)));call(post(Stage1Routes.BUYER+"/precheck"),resident,command,422);
        command.put("items",items);for(String field:List.of("mode","priceCent","commissionCent","orderId","goodsId")){var injected=new LinkedHashMap<>(command);injected.put(field,"REAL");call(post(Stage1Routes.BUYER+"/precheck"),resident,injected,422);}
        command.put("pointId",redemption);assertTrue(call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200).getAsJsonArray("reasonCodes").toString().contains("POINT_UNAVAILABLE"));command.put("pointId",pickup);
        var other=ownerFixture();var foreign=new LinkedHashMap<>(command);foreign.put("storeId",other.store());call(post(Stage1Routes.BUYER+"/precheck"),resident,foreign,404);
        var countsBefore=factCounts();var redisBefore=redisFacts();long reads=observedSqlReads.get();forbidSqlWrites.set(true);try{
            for(int i=0;i<100;i++)assertEquals("PASS",call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200).get("status").getAsString());
            var missing=new LinkedHashMap<>(command);missing.remove("pointId");var blocked=new LinkedHashMap<>(command);blocked.put("items",List.of(map("skuId",aSku,"quantity",11)));var invalid=new LinkedHashMap<>(command);invalid.put("items",List.of(map("skuId",aSku,"quantity",0)));
            for(int i=0;i<100;i++){assertEquals("INPUT_REQUIRED",call(post(Stage1Routes.BUYER+"/precheck"),resident,missing,200).get("status").getAsString());assertEquals("BLOCKED",call(post(Stage1Routes.BUYER+"/precheck"),resident,blocked,200).get("status").getAsString());call(post(Stage1Routes.BUYER+"/precheck"),resident,invalid,422);call(post(Stage1Routes.BUYER+"/precheck"),resident,foreign,404);}
        }finally{forbidSqlWrites.remove();}
        assertEquals(countsBefore,factCounts());assertEquals(redisBefore,redisFacts());assertTrue(observedSqlReads.get()>reads+400);assertEquals(10,db.count("SELECT quantity FROM li_goods_sku WHERE id=?",aSku));assertFalse(result.toString().matches(".*(?:costCent|commissionCent|orderTotal|orderId|paymentId).*"));
        call(post(Stage1Routes.STORE+"/points/"+pickup+"/disable"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"reason","S1_TEST交集即时消失"),200);var noCommon=call(post(Stage1Routes.BUYER+"/precheck"),resident,command,200);assertEquals("BLOCKED",noCommon.get("status").getAsString());assertTrue(noCommon.getAsJsonArray("reasonCodes").toString().contains("NO_COMMON_METHOD"));assertTrue((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));
        observations.add(map("case","BND-013-Q-012","readOnlyRequests",500,"statuses",List.of("PASS","INPUT_REQUIRED","BLOCKED","422","404"),"jdbcWritesRejected",true,"redisUnchanged",true,"durableFactsUnchanged",true,"noAutoSplit",true));
    }
    static Map<String,Long> factCounts(){Map<String,Long> result=new TreeMap<>();for(String table:List.of("li_p0_operation","li_p0_audit","li_p0_outbox","li_p0_inventory_adjustment","li_goods","li_goods_sku","li_p0_goods_control","li_p0_goods_review","li_p0_channel_operation"))result.put(table,db.count("SELECT COUNT(*) FROM "+table));return result;}
    static Map<String,String> redisFacts(){var result=new TreeMap<String,String>();for(String key:Objects.requireNonNull(redis.keys("*")))result.put(key,digest(Objects.requireNonNull(redis.dump(key))));return result;}
    @Test void categoryCertificateFailureIsLimitedToItsLeafAndBothSummariesExposeThatLeaf()throws Exception{
        var owner=ownerFixture();agreementFixture(owner,0,LocalDate.now(Stage1Rules.ZONE),null);
        String type="S1_TEST_CATEGORY_"+testId.substring(0,12);db.update("INSERT INTO li_p0_qualification_type(code,name,scope,required_fields,enabled,source) VALUES(?,'S1_TEST专项材料','CATEGORY','[\"number\",\"holder\",\"issuer\"]',1,'S1_TEST')",type);
        String affected=Stage1BusinessBoundaryTest.category(category,"S1_TEST专项",0,200).get("id").getAsString(),other=Stage1BusinessBoundaryTest.category(category,"S1_TEST普通",0,200).get("id").getAsString();
        call(put(Stage1Routes.MANAGER+"/categories/"+affected),operator,map("requestId",req(),"expectedVersion",0,"name","S1_TEST专项","parentId",category,"sort",0,"qualificationTypes",List.of(type),"reason","S1_TEST专项规则"),200);
        call(post(Stage1Routes.MANAGER+"/categories/"+affected+"/enable"),operator,map("requestId",req(),"expectedVersion",1,"reason","S1_TEST启用专项"),200);call(post(Stage1Routes.MANAGER+"/categories/"+other+"/enable"),operator,map("requestId",req(),"expectedVersion",0,"reason","S1_TEST启用普通"),200);
        assertFalse((Boolean)eligibility.evaluate(owner.store(),affected,null).get("BASIC_ELIGIBLE"));assertTrue((Boolean)eligibility.evaluate(owner.store(),other,null).get("BASIC_ELIGIBLE"));
        var summary=call(get(Stage1Routes.STORE+"/eligibility"),owner.login().session(),null,200);assertTrue(summary.get("BASIC_ELIGIBLE").getAsBoolean());assertEquals(2,summary.getAsJsonArray("categories").size());assertTrue(summary.getAsJsonArray("categories").toString().contains(type));
        var qualification=map("type",type,"number","S1_TEST证号","holder","S1_TEST合成主体","issuer","S1_TEST签发","validFrom",LocalDate.now(Stage1Rules.ZONE).toString(),"validThrough",LocalDate.now(Stage1Rules.ZONE).plusDays(1).toString(),"longTerm",false,"fileIds",List.of(upload(owner.login().session(),Stage1Routes.STORE)),"categoryIds",List.of(affected));
        var draft=call(post(Stage1Routes.STORE+"/qualifications"),owner.login().session(),map("requestId",req(),"payload",map("qualifications",List.of(qualification))),200);String id=draft.get("id").getAsString();call(post(Stage1Routes.STORE+"/qualifications/"+id+"/submit"),owner.login().session(),map("requestId",req(),"expectedVersion",0),200);call(post(Stage1Routes.MANAGER+"/applications/"+id+"/approve"),reviewer,map("requestId",req(),"expectedVersion",1,"revision",1),200);
        assertTrue((Boolean)eligibility.evaluate(owner.store(),affected,null).get("BASIC_ELIGIBLE"));String certificate=String.valueOf(db.required("SELECT id FROM li_p0_qualification WHERE store_id=? AND type=?",owner.store(),type).get("id"));call(post(Stage1Routes.MANAGER+"/qualifications/"+certificate+"/revoke"),reviewer,map("requestId",req(),"expectedVersion",0,"reason","S1_TEST仅专项失效"),200);
        assertFalse((Boolean)eligibility.evaluate(owner.store(),affected,null).get("BASIC_ELIGIBLE"));assertTrue((Boolean)eligibility.evaluate(owner.store(),other,null).get("BASIC_ELIGIBLE"));
        var manager=call(get(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/eligibility"),operator,null,200);var merchant=call(get(Stage1Routes.STORE+"/eligibility"),owner.login().session(),null,200);assertEquals(manager.get("sourceFingerprint"),merchant.get("sourceFingerprint"));assertEquals(manager.getAsJsonArray("categories").get(0).getAsJsonObject().get("sourceFingerprint"),merchant.getAsJsonArray("categories").get(0).getAsJsonObject().get("sourceFingerprint"));
        observations.add(map("case","S04-category-scope","leafCount",2,"unaffectedCategoryRemainsEligible",true,"sameCrossDomainSourceVersion",true));
    }
